import{r as e,t}from"./jsx-runtime-BkSabwWG.js";import{t as n}from"./react-DHmoMYoq.js";import{u as GW}from"./curriculum-DfTyNfqQ.js";var l=e(n(),1),h=t();
var P={"1":[{"b":"Hand drum, floor-spot markers (tape or paper dots), seating-chart sheet and pencil","i":[[3,"Hello Song, so–mi","Greet the class on so and mi at the door of the Music room. Sing the Hello Song for Grade One from the book’s master sheet, then ask “what’s your name?” on so–mi for the class to echo."],[6,"Floor spots and seating chart","In the Music room, children sit on the floor in three or four rows with the shortest at the front. Put a marker at each spot and fill in the seating chart as they settle. Rehearse walking in, sitting on a spot, and walking out."],[5,"Our Music room rules","Talk through three short rules in your own words: listen, wait to be invited to play, and kind hands and voices. For each rule show a thumbs-up example and a thumbs-down example, and practise the quiet hand once."],[4,"Follow the leader on the pulse","Sit tall and copy your simple moves to the drum: pat knees, clap, tap shoulders. Start with both hands together, eight beats for each move, and stop the drum to freeze."],[2,"Line up on the pulse","Drum a slow pulse. One row at a time walks to the door on the drum and freezes."]]},{"b":"Hand drum, tambourine, woodblock and beater","i":[[2,"Hello Song, so–mi","Greet children by name on so–mi and let them echo it back."],[5,"Welcome Back to School (book p. 2)","Teach the song from the book, patting the pulse on your knees. Then everyone pats and counts to eight together. (The song words are in the book and are not copied here.)"],[5,"Instrument manners","Show the three instruments one at a time: how it is held, where it is hit, and its rest position (resting on your lap, hands still). Children copy the hold in the air with no sound."],[6,"Pass and play","Pass the three instruments around the circle while everyone pats the pulse. When you stop, the three holders play eight beats while the others count on their fingers. Then they pass and you go again."],[2,"Line up on the pulse","One row at a time walks to the door on the drum."]]},{"b":"Hand drum, and Mortimer by Robert Munsch if you have it","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[5,"Move and Freeze + 10-second checks + 10-second checks","Everyone moves around the room to the drum: tiptoe, march, crawl low. Stop the drum to freeze. Then ask whether the drum was the same as before or different (faster, slower, higher, lower). Rotating check, group A (about 7 children): while the game runs, give each child a 10-second solo: tiptoe four steps to the drum and freeze when it stops. Mark Y or N on the record sheet."],[4,"Five Little Monkeys (book p. 3)","Say the monkey rhyme from the book. Hands go high on the high lines and low on the low lines, and fingers count down."],[5,"Read-aloud · Mortimer","Use the book guide. The class sings Mortimer’s noise line in a singing voice and speaks the family’s lines in a talking voice. Name each voice as it comes."],[2,"Follow the leader review","Repeat one move from Day 1 for sixteen beats while the drum fades out. Did we stay together?"],[2,"Line up on the pulse","Walk and freeze at the door."]]}],"2":[{"b":"Hand drum","i":[[2,"Hello Song, so–mi","Greet children on so–mi with a favourite ice-cream flavour for the name echo."],[6,"Two Little Apples (book p. 4)","Say the apple rhyme with one action per line. Do one line the same way twice, then change the action on the next line. The class says “same” or “different.”"],[6,"Clap, Clap, Clap Your Hands (book p. 4)","Teach the song by ear. Verse 1 pats knees, verse 2 taps the head, verse 3 touches the floor. Ask the class to invent the move for verse 4."],[4,"Moving to the pulse (book p. 5)","Walk to the drum and freeze when it stops. Play a faster drum, then a slower one, and ask for a new path each time: circle, zigzag, straight."],[2,"Line up on the pulse","Walk to the door on the drum and freeze."]]},{"b":"Hand drum, woodblock and beater","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[5,"I Think Music’s Neat (book p. 5)","Teach the song from the book while everyone pats the pulse. Let a different child lead the pats on each repeat."],[6,"Hickory, Dickory, Dock (book p. 5)","Say the rhyme. Fingers climb up on “up” and slide down on “down.” One child keeps the pulse on the woodblock while the others tap it on their knees."],[4,"Read-aloud · Hand, Hand, Fingers, Thumb","Use the book guide. Everyone pats the pulse on their laps the whole time; the words change but the pats stay even."],[2,"Fast or slow?","Walk the pulse. Speed up the drum a little, then slow it. Class says fast or slow."],[1,"Line up on the pulse","One row at a time on the drum."]]},{"b":"Hand drum, one shaker","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[6,"Monkey See and Monkey Do (book p. 6)","Teach the song from the book. One “monkey” sits on a chair and leads a pulse action; the class copies. Change leaders every eight beats."],[4,"Five Little Monkeys, review (book p. 6)","Say the rhyme again. Hands go high and low as in Week 1."],[6,"Pulse leader + 10-second checks + 10-second checks","Children take turns holding the shaker and leading eight steady beats while the class copies on knees. While the game runs, give each child a short solo. Rotating check, group B (about 7 children): while the game runs, give each child a 10-second solo: pat eight even beats on their knees with the drum. Mark Y or N on the record sheet."],[2,"Line up on the pulse","Pat, then walk to the door on the drum."]]}],"3":[{"b":"Hand drum, woodblock and beater, whiteboard marker, bean bag","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[6,"I Think Music’s Neat: draw the beat (book p. 7)","Sing the song while everyone pats the pulse. As they pat, draw one heart for each beat on the board, eight to a line. Count the hearts together. The hearts are the steady beat; they have no other name yet."],[6,"Moving high and low (book p. 7)","Play the low drum and everyone crouches, walking low. Play the high woodblock and everyone tiptoes tall. Mix them up and keep the pulse steady."],[4,"Sing Me Your Name (book p. 8)","Pass the bean bag around the circle. The holder sings “my name is ___” on so–mi and the class sings it back."],[2,"Line up on the pulse","Walk on the pulse and freeze at the door."]]},{"b":"Three to five woodblocks and beaters, hand drum, the Syncopated Clock recording","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[7,"Hickory, Dickory, Dock: tick-tock pulse (book p. 9)","Split the class. Half whisper “tick-tock” on the pulse while the other half says the rhyme. Then swap. Swing arms like a pendulum."],[6,"Woodblock tick-tock","Three to five children play the tick-tock pulse on woodblocks while the class says the rhyme. Rotate players every two times through."],[3,"The Syncopated Clock (book p. 9)","Play the LeRoy Anderson recording. Follow the leader: sway side to side, windshield-wiper fingers, then elbows up and down, all on the beat."],[2,"Line up on the pulse","Tick-tock walk to the door."]]},{"b":"Bean bag, hand drum, and The Listening Walk by Paul Showers if you have it","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[5,"Look at Me (book p. 8)","Teach the so–mi singing game from the book. Freeze with a smile when the song ends."],[6,"Read-aloud · The Listening Walk","Use the book guide. Raise the quiet hand after every few sounds; everyone freezes and listens, then the next page."],[5,"Sing Me Your Name + 10-second checks + 10-second checks","Pass the bean bag. Each child sings their own name on so–mi while the class listens. Give each child a short solo. Rotating check, group C (about 7 children): while the game runs, give each child a 10-second solo: sing their own name on so and mi. Mark Y or N on the record sheet."],[2,"Line up on the pulse","Walk and freeze at the door."]]}],"4":[{"b":"Glockenspiel or xylophone, mallets, hand drum, a puppet if you like","i":[[2,"Hello Song, so–mi","Greet children on so–mi. Offer a favourite colour for the name echo."],[4,"Moving up and down (book p. 10)","Voices slide up like a rocket and down like a slide, and hands and bodies follow. Then play a glissando up and down on the bars and ask “up or down?”"],[8,"Playing up and down: mallet manners (book p. 10)","Show a gentle mallet hold and a relaxed bounce. Two or three children at a time play up and down the bars while the class sings a slide. Everyone gets a turn over Days 1–3."],[4,"Sing Me Your Name, favourite colour (book p. 10)","Pass the bean bag around the circle. The holder sings their name and a favourite colour on so–mi and the class echoes."],[2,"Line up on the pulse","Drum a slow pulse and freeze at the door."]]},{"b":"Xylophone, glockenspiel, woodblock and mallets","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[4,"Hickory, Dickory, Dock, speak (book p. 11)","Say the rhyme with a climbing hand on “up the clock” and a sliding hand on “ran down.”"],[8,"Hickory with instruments (book p. 11)","One child plays the pulse on a woodblock. A pair plays the tune on so and mi bars on the xylophone. The glockenspiel slides up on “up the clock” and down on “ran down.” Tiptoe around the circle while players swap."],[4,"Mallet manners","Between players, name the three ways to treat a mallet: hold it, rest it, and give it back. Practise rest position."],[2,"Line up on the pulse","Tiptoe to the door."]]},{"b":"Hand drum, glockenspiel and mallets, heart cards","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[4,"Moving with style (book p. 12)","Move to the pulse in different styles: giant, floppy, tiny, tiptoe. Stop the drum to freeze."],[6,"Saw, Saw, Saw Away + 10-second checks (book p. 12) + 10-second checks","Say the saw rhyme from the book with a sawing motion on each beat. Children invent a new verse. Give each child a short solo. Rotating check, group D (about 7 children): while the game runs, give each child a 10-second solo: keep eight even pats on their knees while the drum fades. Mark Y or N on the record sheet."],[4,"Read-aloud · Rain, Rain, Go Away!","Use the book guide. Sing the verses and show high and low with hands. Take a moment to glissando up and down on the glockenspiel at the end."],[2,"Heart rows","Lay out a row of eight hearts and point to one on every pulse. We count them. The name for a beat arrives in November."],[2,"Line up on the pulse","Walk and freeze at the door."]]}],"5":[{"b":"Hand drum, whiteboard and marker, eight muffin pictures (or paper circles) to put on plates","i":[[3,"Hello and beat review","This year: walk and pat the pulse to the drum, freeze when it stops, and sing the Hello Song on so–mi. Use this review each time the class has missed earlier weeks."],[5,"The Muffin Man (book p. 13)","Sing the song in your own voice. Pat the pulse while you sing. A page on this site has the words."],[5,"Eight plates, eight muffins","Draw two rows of four plates. Put one muffin on each. Point to the plates one by one on the pulse and the class says “yum” for each. Use these eight yums between verses."],[5,"Take away a muffin","One child wipes a muffin off a plate. Point to the plates on the pulse again: say “yum” where there is a muffin and stay silent but still on the empty plate."],[2,"Line up on the pulse","Silent beats at the door: walk to the drum and freeze when it stops."]]},{"b":"Pentatonic xylophone and mallets, woodblock, hand drum","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[5,"Fang and Twang (book p. 14)","Use the book’s two puppets for call-and-response hellos on so–mi. One puppet sings, the class and the other puppet answer. Pass the puppets around the circle."],[5,"Eency Weency Spider / Itsy Bitsy Spider (book p. 15)","Finger play on the pulse: climb, wash down, sun, climb. Between verses, tap a body part. A page on this site has the words."],[6,"Legs and All on the xylophone (book p. 15)","Say the book’s poem together. One child plays the pulse on the xylophone with a gentle two-mallet bounce while the class pats the pulse; at the end of the line the next child steps in. Everyone gets a turn across the three days."],[2,"Line up on the pulse","Walk on the drum and freeze at the door."]]},{"b":"Hand drum, tambourine, and The Quiet Book by Deborah Underwood if you have it","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[4,"Moving like a spider (book p. 16)","Spiders creep in place at their desks, or around the carpet, on the drum. Stop the drum and everyone freezes. When it starts again, they creep on, a little faster or slower."],[4,"Criss-Cross Applesauce (book p. 16)","Say the rhyme from the book with partner back actions. Keep the actions on the pulse."],[4,"Read-aloud · The Quiet Book","Use the book guide. Pat three beats, hold still on the fourth, and read a quiet page."],[5,"Muffin Man silent beats + 10-second checks + 10-second checks","Sing The Muffin Man with the plates on the board. Wipe a muffin and the class stays silent but still on that plate. While the game runs, give each child a short solo. Rotating check, group A (about 7 children): while the game runs, give each child a 10-second solo: say “yum” on the pulse for four plates and stay silent but still on the empty one. Mark Y or N on the record sheet."],[1,"Line up on the pulse","Walk and freeze at the door."]]}],"6":[{"b":"Hand drum, whiteboard and marker, muffin pictures","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[6,"Muffin Man: the silent beat (book p. 17)","Sing the song. Eight plates on the board: sound where a muffin sits, and where a plate is empty everyone touches their shoulders in silence. Use the book’s chart if you have it."],[6,"Big Black Cats (book p. 17)","Say the cat poem from the book. The class finds which lines match and which differ. Echo it phrase by phrase with a clap on the pulse."],[4,"Walk or jog? (book p. 17)","Take one step on each beat for a walk, and two quick steps on a beat for a jog. Follow the poem’s words: some beats walk and some jog."],[2,"Line up on the pulse","Walk and jog to the door on the drum."]]},{"b":"Four woodblocks and beaters, xylophone, hand drum","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[5,"Big Black Cats body percussion (book p. 18)","Clap on walking beats and pat on jogging beats. Keep all other children on body percussion and voice."],[6,"Four woodblocks in the interlude (book p. 18)","Four children play the pulse on woodblocks between verses. Pass the woodblocks around during the interlude so every child gets a turn over the three days."],[5,"Eency Weency Spider (book pp. 18–19)","Finger play with the tune. Then discover that the tune goes up and down. One child plays a simple one-mallet pattern up the xylophone and back down while the class sings."],[2,"Line up on the pulse","Walk and freeze at the door."]]},{"b":"Hand drum, shaker, and The Very Busy Spider by Eric Carle if you have it","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[6,"Read-aloud · The Very Busy Spider (book p. 19)","Use the book guide. Pat the pulse and say the spider’s repeating working line on the beat. When the animals interrupt, hold still for one beat."],[4,"Itsy Bitsy Spider movement (book p. 19)","Play the recording named in the book. Follow the leader: copy the pulse actions you lead, then a child leads."],[6,"Silent-beat shoulders + 10-second checks + 10-second checks","Chant a four-beat line of your choice. Pat three beats and touch shoulders on the fourth. While the game runs, give each child a short solo. Rotating check, group B (about 7 children): while the game runs, give each child a 10-second solo: pat three beats on their knees and touch shoulders on the fourth. Mark Y or N on the record sheet."],[2,"Line up on the pulse","Silent last beat at the door."]]}],"7":[{"b":"Hand drum, four sheets of paper and tape, bean bag","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[4,"Stirring My Brew (book p. 20)","Say the stirring chant in a whisper, then in a talking voice, then in a strong voice. Use the words quiet and strong, not “soft.”"],[7,"Paper beats: stand on the walk and jog (book p. 20)","Tape four sheets to the carpet or floor at the front, one for each beat. Children stand one to a sheet for a walking beat, and two to a sheet for a jogging beat. Use the rhythm of Big Black Cats."],[5,"Big Black Cats body percussion (book p. 20)","Say the cat poem. Clap on walking beats and pat on jogging beats. Keep the silent beat if the poem has one."],[2,"Line up on the pulse","Walk and jog to the door."]]},{"b":"Four woodblocks and beaters, glockenspiel, hand drum","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[2,"Stirring My Brew (book p. 20)","One quick round: whisper, talking, strong."],[9,"Big Black Cats on instruments (book p. 21)","Woodblocks play on lines 1, 2 and 4 of the poem and the glockenspiel (set to a pentatonic scale) plays on line 3. Pass the instruments around the circle during the interlude. Other children say the poem and clap and pat."],[5,"Hippity Hop (book p. 21)","Teach the nursery rhyme from the book. Pat the big beats, then echo by line."],[2,"Line up on the pulse","Walk and freeze at the door."]]},{"b":"Yarn ball or bean bag, xylophone and glockenspiel, mallets, and My Family Plays Music by Judy Cox if you have it","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[6,"Hippity Hop toss + 10-second checks (book p. 21) + 10-second checks","Sing the nursery rhyme while tossing a yarn ball or bean bag around the circle. The catcher answers a question such as “What is your favourite candy?” Give each child a short solo. Rotating check, group C (about 7 children): while the game runs, give each child a 10-second solo: say a favourite candy first in a whisper and then in a strong voice. Mark Y or N on the record sheet."],[6,"Candy Store: steady two-note accompaniment (book p. 22)","Teach the song from the book. Two children play two bars on a pulse underneath while the class sings. Add a word-chain of candy words between verses and swap players."],[4,"Read-aloud · My Family Plays Music","Use the book guide. For each instrument named, play it four times on the beat."],[2,"Line up on the pulse","Walk on the drum and freeze at the door."]]}],"8":[{"b":"Hand drum, speaker and the In the Hall of the Mountain King recording","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[7,"In the Hall of the Mountain King (book p. 23)","Play Grieg’s recording. Follow the leader: copy pulse actions that change at the end of each musical sentence. Start with both hands together, then alternate. Let the music speed up and the actions speed up with it."],[7,"Little Jack Pumpkin Face (book p. 23)","Echo the Halloween rhyme with four actions, one for each line: tap the floor, pat knees, clap getting bigger, snap. Ask how many musical sentences the rhyme has. Four."],[2,"Eency Weency Spider finger play","Quick finger play to keep the pulse. The words are on this site."],[2,"Line up on the pulse","Walk and freeze at the door."]]},{"b":"Xylophone, glockenspiel, mallets, hand drum","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[9,"What Will You Be? (book p. 24)","Teach the song from the book. Two children play a steady two-note accompaniment on bars under the singing. A child whispers what they will be for Halloween, goes to the bars, and plays while the class sings. Rotate players each verse."],[5,"Little Jack Pumpkin Face: say, think, say (book p. 23)","Say the rhyme, then think it in your head with only the actions, then say it again. Keep the actions on the pulse."],[2,"Mountain King, listen again","A short listen. Wave a finger for each musical sentence."],[2,"Line up on the pulse","Walk and freeze at the door."]]},{"b":"Hand drum, From Head to Toe by Eric Carle if you have it","i":[[2,"Hello Song, so–mi","Greet children on so–mi."],[6,"Legs and All again (book p. 24)","Say the poem from the book. Lay out a row of hearts for the pulse and point to a heart on each beat. Find the beats that need two quick sounds and show them with fast pat-pat."],[6,"Pumpkin Face musical-sentence game + 10-second checks + 10-second checks","Each child leads one sentence of Little Jack Pumpkin Face with an action while the class copies. Give each child a short solo. Rotating check, group D (about 7 children): while the game runs, give each child a 10-second solo: lead one sentence of Little Jack Pumpkin Face with an action on the pulse. Mark Y or N on the record sheet."],[4,"Read-aloud · From Head to Toe","Use the book guide. Echo each move four times on the beat."],[2,"Line up on the pulse","Walk and freeze at the door."]]}],"9":[{"b":"Hand drum, 4 heart cards, ta cards","i":[[2,"Hello Song, so–mi","Greet children on so–mi. Pat the pulse and say ta under the last phrase."],[5,"Hearts become ta (book idea, Nov)","Point to four hearts. “Each heart is one pulse. We call it ta.” Put a ta card under each heart. Say and clap ta ta ta ta."],[6,"Engine Engine Number Nine (book pp. 26–27)","Teach the chant from the book. Slide palms back and forth on the pulse, then transfer the pulse to a scraped drum. Echo by phrase. Try it slow, then a little faster — still even."],[5,"Eight-beat introduction","One child scrapes eight tas on the drum before the class speaks. Call that little wait the introduction: something short that happens at the beginning. Then the class comes in together."],[2,"Line up on the pulse","Whisper ta ta ta ta to the door."]]},{"b":"Hand drum, barred instrument or xylophone (one), Chicka Chicka Boom Boom if you have it","i":[[2,"Hello Song, so–mi","Greet on so–mi; class answers on ta pats."],[4,"Engine Engine with a two-note accompaniment (book p. 27)","Two children play a gentle two-note pulse on the bars after the drum introduction. Other children speak and march a short train in the aisle or carpet. Homeroom: one xylophone carried in; Music room next year: a short line of barred instruments."],[5,"Read-aloud · Chicka Chicka Boom Boom","Use the book guide. Half pats ta; half chants."],[5,"Ta freeze","Walk and say ta; freeze when the drum stops. Restart on ta."],[2,"Train rotate","Drummer hands the drum to the next child and joins the train. Keep turns short."],[2,"Line up on the pulse","Introduction of four tas on the drum, then walk."]]},{"b":"Hand drum, rhythm sticks (optional)","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[5,"Yankee Doodle (book p. 28)","Teach or review from the book (title and page only here). Echo by phrase. Pat on phrases 1 and 3; clap on phrases 2 and 4. March in place on the pulse."],[5,"Ta under Yankee + 10-second checks","Whisper ta on the pulse while a few children pat. Give each checked child a short solo. Rotating check, group A (about 7 children): while the game runs, give each child a 10-second solo: scrape or pat four tas, then freeze for one silent beat. Mark Y or N on the record sheet."],[6,"Ask the class","“Was Yankee Doodle new to you?” Keep answers short."],[2,"Line up on the pulse","March on ta to the door."]]}],"10":[{"b":"Hand drum (optional squirrel puppet)","i":[[2,"Hello Song, so–mi","Greet on so–mi; pat ta underneath."],[5,"The Squirrel poem (book p. 29)","Read the poem from the book. Class guesses the animal. Second time, children hop, twirl, and crouch in place as the words suggest — keep a quiet ta in the feet."],[6,"Chase the Squirrel (book pp. 29–30)","Teach the song from the book (title and page only). Pat the pulse while you sing. Two children at a carried-in xylophone play a gentle two-note pulse (chord bordun feel) under the singing; others wait in a short line. Homeroom: one or two instruments; Music room next year: four barred instruments in short lines."],[5,"Hop, Old Squirrel (book p. 30)","Sing from the book. Hop three times on “Hop old squirrel,” then freeze and wiggle on the nonsense words. Choose a quiet unpitched sound (shaker or woodblock) for the nonsense bits."],[2,"Line up on the pulse","Hop on ta to the door; freeze on rest."]]},{"b":"Hand drum, train/choo-choo cards or paper rectangles, board","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[5,"Engine Engine with train cards (book p. 31)","Review Engine Engine. Show four cards (two “train” = ta, two “choo-choo” spoken as two even sounds on one beat — feel only; we name ti-ti in February). Build a four-beat row. Open hands on an empty car for rest."],[6,"Label the repeat sign (book p. 31)","Point to the book’s repeat sign (or draw :|| ). Speak the row twice without stopping. Sing–speak–sing (ABA): sing Engine Engine, speak the row twice, sing again."],[5,"America (book p. 31)","Introduce from the book (patriotic repertoire; title and page only). Soft listening or echo of the first phrase if time is short. November is a good time to plant it for later review."],[2,"Line up on the pulse","Speak a ta/rest row once, then walk."]]},{"b":"Hand drum, xylophone, This Jazz Man if you have it","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[5,"Chase the Squirrel turns","Rotate two players on the two-note pulse while the class sings. Keep mallets relaxed."],[5,"Read-aloud · This Jazz Man + 10-second checks","Use the book guide. Pat ta; open hands on rest. Rotating check, group B (about 7 children): while the game runs, give each child a 10-second solo: clap a four-beat row with one rest (open hands on the rest). Mark Y or N on the record sheet."],[6,"Ta/rest solos","Show a four-beat row with one rest. Children clap it; checked children play it once on the drum."],[2,"Line up on the pulse","Ta ta ta rest to the door."]]}],"11":[{"b":"Hand drum","i":[[2,"Hello Song, so–mi","Greet on so–mi. Pat slow ta, then a little faster."],[6,"Walk and Stop (book p. 32)","Teach the song from the book (also scored on this site). Walk on the pulse while singing; freeze on “stop.” Change how long you wait. Freeze in a high or low statue that matches the end of the phrase."],[5,"Wait a Phrase (book p. 32)","Drum a clear four-beat sentence. Children walk for one sentence and wait through the next (tap the drum rim on waiting sentences). Homeroom: walk the perimeter of the carpet; Music room next year: scatter through the open floor."],[5,"Tempo choose","A child picks slow or fast for the next Walk and Stop. Class matches."],[2,"Line up on the pulse","Slow walk; freeze at the door."]]},{"b":"Woodblocks (2–3) and beaters, hand drum, We’re Going on a Bear Hunt if you have it","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[5,"I Can Play the Wood Block (book p. 33)","Teach the song from the book (title and page only). Pass two or three woodblocks around the circle on the pulse so every child gets a short turn. Teacher keeps a quiet accompaniment with voice or drum."],[6,"Read-aloud · We’re Going on a Bear Hunt","Use the book guide. Slow pats, then faster for the run home."],[5,"Now’s the Time (book p. 33)","Speak the thanksgiving rhyme from the book. Class pats a simple pulse ostinato; soloists name one thing they are thankful for on the open beats."],[2,"Line up on the pulse","Pass the last woodblock home, then walk."]]},{"b":"Hand drum, turkey high/low pictures or board drawings","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[5,"Gobble Gobble Gobble (book p. 34)","Teach the song from the book (title and page only). Show high and low turkey pictures; sing high or low (so–mi feel) as you point. Add the circle game: one child walks the pulse around the outside and taps a head on the last word."],[5,"High/low statues","Freeze high or low when the drum stops."],[6,"Walk and Stop review + 10-second checks","One more round. Checked children lead a freeze statue. Rotating check, group C (about 7 children): while the game runs, give each child a 10-second solo: walk four slow tas, then four faster tas, and freeze on the stop. Mark Y or N on the record sheet."],[2,"Line up on the pulse","Gobble quietly on ta to the door."]]}],"12":[{"b":"Hand drum","i":[[2,"Hello Everybody (book p. 35)","Sing while patting ta. Invite leaders to show a new way to keep the pulse (tap head, march in place, pound soft fists). Pass the lead around the circle."],[5,"Voice shapes","Slide up, down, then stay on one sound. Draw each shape in the air."],[6,"Body notation (book p. 35)","Four children stand as beats: one child alone = ta; two children side by side = two sounds on one beat (feel only). Rearrange and clap the row. Add one child with hands on shoulders for rest."],[5,"Ask the class","“What things in your house keep a beat?”"],[2,"Line up on the pulse","New pulse leader walks the class out on ta."]]},{"b":"Popsicle sticks (about 12 per pair) or paper strips, Little Melba if you have it","i":[[2,"Hello Song, so–mi","Greet on so–mi; draw the hello shape in the air."],[5,"Popsicle Stick Game (book p. 36)","Pairs build four-beat rows: one stick = ta; three sticks as a beam = two sounds; a shoulder touch or stick “Z” = rest. Speak and clap. Homeroom: sticks on desks or carpet bags; Music room next year: same game on the floor."],[6,"Read-aloud · Little Melba and Her Big Trombone","Use the book guide. Trace trombone lines."],[5,"Yuki Song (book p. 36)","Play or hum the book’s Native American melody (title and page only; no text in the book). Class pats ta. A few children play the pulse on a drum while others listen for the shape of the tune."],[2,"Line up on the pulse","Hum a hill shape, then walk."]]},{"b":"Hand drum, board and marker","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[5,"Jim Along, Josie (book p. 37)","Teach from the book (also scored on this site). Walk the pulse on the first part; add the face-the-centre claps and turn. Homeroom: circle beside desks or on the carpet."],[5,"I Can Play the Wood Block review (book p. 37)","Quick pass of one unpitched instrument with the song from last week."],[6,"Contour + pulse checks + 10-second checks","Teacher hums up, down, or same; children draw it. Checked children also clap a ta/rest row from sticks. Rotating check, group D (about 7 children): while the game runs, give each child a 10-second solo: draw an up, down, or same shape in the air to match a hummed tune. Mark Y or N on the record sheet."],[2,"Line up on the pulse","Jim Along steps to the door."]]}],"13":[{"b":"Hand drum","i":[[2,"Hello Song, so–mi","Greet on so–mi. Pat a quiet ta under the last phrase."],[5,"Rhythmic Training — phrase echo (book p. 38)","In a standing circle, clap a four-measure pattern in 2/4 that ends on the first beat of measure four. Class echoes. Repeat until steady. Homeroom: stay beside desks or on the carpet circle."],[6,"Weekend Fun (book pp. 38–39)","Teach from the book (title and page only). Echo the melody by two-measure phrases. Sing while patting ta. Then a short so–mi chat: you ask who had weekend fun; a few children answer on so–mi. Keep chats short and kind."],[5,"Ask the class","“What is one fun thing you did?” One or two so–mi answers only."],[2,"Line up on the pulse","Whisper ta ta ta ta to the door."]]},{"b":"Hand drum, triangles or finger cymbals (2–4), one bass xylophone or metallophone if you can carry it, Zin! Zin! Zin! A Violin if you have it","i":[[2,"Hello Song, so–mi","Greet on so–mi; class pats ta."],[5,"Hanukah is Here (book pp. 39–40)","Teach from the book (title and page only). Lead a short, respectful talk about December holidays — invite children who celebrate Hanukkah to share a custom if they wish. Echo the text by phrase. Pat ta while singing (A). Partner hand-game claps on the pulse. B section: tap a half-note pulse (fist on fist) counting to eight. Perform ABA with body first."],[6,"Add colour (homeroom kit)","Map patting to a gentle two-note pulse on one carried-in barred instrument (teacher or two careful players). Map the fist pulse to triangles or finger cymbals. Rotate short turns. Music room next year: BX/BM lines and more metals."],[5,"Read-aloud · Zin! Zin! Zin! A Violin","Use the book guide. Wait, then play together."],[2,"Line up on the pulse","Eight quiet fist pulses, then walk."]]},{"b":"Hand drum or recording device for the dance track, Jim Along Josie","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[5,"Dance for Hanukkah (book p. 40)","Teach Part One body levels: stamp, pat, shoulders, head — eight each. Part Two: partner clap / own clap, then elbow swing. After an eight-beat introduction, the dance repeats. Call that wait the introduction (song doorway). Homeroom: partners beside desks; use a recording if you have Rhythmically Moving 6, or keep a steady drum pulse and count the sets."],[5,"Jim Along, Josie review (book p. 40; also on this site) + 10-second checks","Add verses the class suggests (march, jump, crawl). Keep moves on ta. Rotating check, group A (about 7 children): while the game runs, give each child a 10-second solo: clap or drum an eight-beat introduction, then freeze for the class to enter. Mark Y or N on the record sheet."],[6,"Phrase + doorway checks","Echo a four-measure clap phrase. Checked children play an eight-beat introduction for the class, then everyone comes in on Jim Along."],[2,"Line up on the pulse","Jim Along steps to the door."]]}],"14":[{"b":"Hand drum, optional Nutcracker / Sugar Plum Fairy recording","i":[[2,"Hello Song, so–mi","Greet on so–mi. Clap a short phrase-echo warm-up (review book p. 38 idea)."],[5,"Marionette Game (book p. 41)","Talk about marionettes vs other puppets. Move one “hinge” at a time (wrist, elbow, knee) on a quarter-note pulse while you drum or play Dance of the Sugar Plum Fairy. First theme: bend big hinges. Accents: slump and recover. Soft ending: tiny finger/wrist moves. Homeroom: stay in self-space beside desks; Music room next year: more scatter space."],[6,"Ask the class","“Have you heard this music before? When?” Keep answers short."],[5,"Pulse freeze","Move on ta; freeze when the drum stops."],[2,"Line up on the pulse","Tiny marionette steps to the door."]]},{"b":"Toy picture cards or board sketches (soldier, airplane, rocking horse, bike), tambourine, woodblock, cowbell or similar, vibraslap or shaker, Clap Your Hands if you have it","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[4,"Time for Toys (book pp. 42–43)","Teach from the book (title and page only). Show four toy cards. Speak each toy’s rhythm (soldier, airplane, rocking horse, bike). Bike stays last so the chain ends on beat seven. Four children hold cards; class speaks the chain twice. Then song (A) twice and word chain (B) twice. Homeroom kit: put four unpitched instruments on the floor with a card beside each; first player in each short line plays only their toy’s rhythm; rotate back during the song."],[7,"Read-aloud · Clap Your Hands","Use the book guide. Moves on the pulse."],[5,"Same or different","Speak two toy chains; class shows same or different with arms."],[2,"Line up on the pulse","Speak “bike” on the last beat, then walk."]]},{"b":"Ratchet or scraper, hand drum, Teddy Bear","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[5,"Jack-in-the-Box (book p. 43)","Speak the poem from the book (title and page only) while tapping shoulders on the pulse. Press a “Jack,” mime winding, then a drum pop. That child becomes the next leader. Add ratchet for wind and drum for pop. Extension: 1, then 2, then 4 Jacks."],[5,"Teddy Bear (book p. 43; also on this site) + 10-second checks","Sing with the usual actions. On “Teddy bear,” show high–high–low (head, head, shoulders). Perform three times: sing / think (inner hearing) with actions / sing — same, different, same. Rotating check, group B (about 7 children): while the game runs, give each child a 10-second solo: play one toy rhythm once on an unpitched instrument, then freeze. Mark Y or N on the record sheet."],[6,"Toy + Teddy checks","Checked children play one toy rhythm on an unpitched instrument, then show high-high-low for “Teddy bear.”"],[2,"Line up on the pulse","Teddy Bear tip-toe to the door."]]}],"15":[{"b":"Hand drum, board or chart for Teddy Bear high/low","i":[[2,"Hello Song, so–mi","Greet on so–mi. One short phrase-echo clap pattern (book p. 38 idea)."],[5,"Teddy Bear with chart (book p. 44)","Review Teddy Bear (on this site). Show a simple high/low chart for “Teddy bear” (two highs, one low). Sing “high, high, low” in place of those words. Class invents new body pairs (shoulders/knees, waist/toes). Perform sing / think / sing."],[6,"Phrase rainbows","Each Teddy Bear line gets one rainbow arm. How many phrases?"],[5,"Same-different-same","Sing, think with actions, sing again."],[2,"Line up on the pulse","High-high-low tip-toe to the door."]]},{"b":"Popsicle sticks (about 12 per pair) or paper strips, Polar Bear book if you have it","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[5,"La Piñata (book p. 45)","Teach from the book (Mexican folk; title and page only). Short talk about the piñata tradition. Echo Spanish text by two-measure phrases using the book’s pronunciation guide in class (not copied here). Add clap/pat body percussion from the book’s idea. Partners may invent a gentle hand game. Homeroom: circle on carpet; keep hand games low."],[6,"Popsicle Stick Game (book p. 45; see also p. 36)","Pairs build rhythms from familiar titles: Teddy bear; Dale dale dale; Dashing through the snow; Up on the housetop. Use one stick = ta, two short sounds on one beat (beam), and a rest. Speak and clap. Homeroom: sticks on desks."],[5,"Read-aloud · Polar Bear, Polar Bear","Use the book guide. One phrase per animal turn."],[2,"Line up on the pulse","Clap one stick row once, then walk."]]},{"b":"Holiday pattern chart or board, shakers or jingle bells, optional Jingle Bells instrumental recording","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[5,"Oh What Fun! (book p. 46)","Show four holiday rhythm patterns from the book chart (title and page only; draw simple ta / two-short / rest rows yourself). Speak with rhythm syllables you already use; review the repeat sign. Point to numbers while the class claps quietly (two-finger clap). Optional: clap along with an instrumental Jingle Bells while you change patterns."],[5,"Traditional holiday songs (book p. 46) + 10-second checks","Build seasonal repertoire by title only (for example Jingle Bells chorus on this site; Up on the Housetop; other secular seasonal songs your school uses). Keep it light and inclusive — offer a non-holiday winter song if a family prefers. Rotating check, group C (about 7 children): while the game runs, give each child a 10-second solo: clap one four-beat holiday row (ta, two-shorts, rest) and freeze. Mark Y or N on the record sheet."],[6,"Pattern + phrase checks","Checked children clap one Oh What Fun row and draw one phrase rainbow for Teddy Bear or La Piñata."],[2,"Line up on the pulse","Jingle the pulse to the door."]]}],"16":[{"b":"Hand drum","i":[[2,"Hello Song, so–mi","Greet on so–mi. Pat a quiet ta under the last phrase."],[5,"Christmas Now is Over (book p. 47)","Teach from the book (title and page only; use “someone” in place of any gift-giver name your school prefers). Echo by phrase while students pat the pulse. Choose a four-beat ostinato (for example pat, pat, clap, clap). After the poem, four children share a favourite gift or winter experience — unmetered and short. Homeroom: seated circle on the carpet."],[6,"Ask the class","“What was one favourite gift or winter fun?” One or two answers only."],[5,"Pulse ostinato switch","Change the ostinato; class follows your lead for one more poem pass."],[2,"Line up on the pulse","Whisper ta ta ta ta to the door."]]},{"b":"Board and marker, rhythm sticks (one pair per child or shared), one bass xylophone or metallophone if you can carry it","i":[[2,"Hello Song, so–mi","Greet on so–mi; class pats ta."],[5,"Creating a Word Chain (book p. 48)","From favourite gifts, choose words that fit two beats with ta, ti-ti, and rest (title and page only — write your own stick notation on the board). Speak and clap each gift; list text and rhythm. Class orders a chain; speak and clap, then play on rhythm sticks twice. Homeroom kit: sticks on desks."],[6,"Lucky Me! (book pp. 48–49)","Teach from the book (title and page only). Echo melody by two-measure phrases. Pat a simple chord-bordun feel, then march while singing (sticks rest on shoulders). Alternate song and the word chain (same/different). Homeroom: one carried-in barred instrument for the teacher bordun if available; Music room next year: full BX/BM."],[5,"Same or different","Play song then chain; class shows same or different with arms."],[2,"Line up on the pulse","March four tas to the door."]]},{"b":"Hand-signal cards if you have them (Appendix C idea), Teddy Bear, Do Re Mi book if you have it","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[5,"Labeling SM (book p. 49)","After months of singing so–mi songs, name So and Mi and show Curwen hand signs (book sequence: high/low taps, then names and signs). Combine so and mi in four-beat patterns with both hands; so near mouth level, mi below the chin. Ask: “What songs have we sung on so and mi?”"],[5,"Teddy Bear with so–so–mi (book p. 49; also on this site) + 10-second checks","Review Teddy Bear. Discover that “Teddy bear” = so–so–mi. Sing again, substituting so–so–mi with hand signs on each “Teddy bear.” Rotating check, group D (about 7 children): while the game runs, give each child a 10-second solo: sing and sign a four-beat so–mi pattern, then freeze. Mark Y or N on the record sheet."],[6,"So–mi + Teddy checks","Checked children sing and sign one four-beat so–mi pattern, then show so–so–mi on “Teddy bear.”"],[2,"Line up on the pulse","So–so–mi tip-toe to the door."]]}],"17":[{"b":"Hand drum, hand-signal cards if posted, board and marker","i":[[2,"Hello Song, so–mi","Greet on so–mi. Short phrase-echo clap (book p. 38 idea)."],[5,"Rhythmic Training (book p. 50)","Review four-measure phrase echoes in 2/4 with one, two, or three body-percussion levels (stamp with alternating feet). Homeroom: stay beside desks."],[6,"Melodic Training — SM (book p. 50)","Standing circle: echo four-beat so–mi patterns with hand signs (start on so). Light singing tone; good posture."],[5,"Ta to ti-ti on the board (book p. 50)","Draw four tas; speak, speak-and-clap, clap. Change one ta to ti-ti and repeat. Prepares the paper assessment later."],[2,"Line up on the pulse","So–mi tip-toe to the door."]]},{"b":"Form-shape cards or board sketches (square, circle, triangle…), one glockenspiel or xylophone with only G and E if possible, Up, Up, Down if you have it","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[5,"Moving with Shapes (book p. 51)","Four or five children pick shapes. Class assigns a locomotor move to each (march, gallop, tip-toe). Hold up a shape → move; put it down → freeze. Extension: a student conductor points along a shape row. Homeroom: small self-space beside desks; skip gallop if space is tight."],[6,"Valentine / SSM on bars (book pp. 51–52)","Review Teddy Bear with so–so–mi signs. Substitute “Valentine” for every so–so–mi. Demonstrate S–S–M (G–G–E) on a vertical glockenspiel (only G and E if you can). One child plays; then half play SSM on the barred instrument while half do Teddy actions. Homeroom kit: one carried-in glock or xylo; rotate short turns."],[5,"Read-aloud · Up, Up, Down","Use the book guide. High and low bodies."],[2,"Line up on the pulse","Valentine so–so–mi to the door."]]},{"b":"Three-line staff cards and disks if you have them (or paper staffs), Engine Engine","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[5,"Notating So-Mi (book p. 52)","Pairs share one three-line staff. Middle line = so; partners place mi. You sing fragments (SSM, SMS); class echoes, then notates. Melody moves left to right — disks do not stack. Extension: notate a bit of Valentine, Engine Engine, or Lucky Me."],[5,"What Shall We Do When We All Go Out? (book p. 51) + 10-second checks","Teach from the book (title and page only). Echo by phrase. After the song, one outdoor or winter idea; class pantomimes while you keep a pulse on drum or piano. Homeroom: scattered beside desks. Rotating check, group A (about 7 children): while the game runs, give each child a 10-second solo: place so and mi on a three-line staff, then freeze. Mark Y or N on the record sheet."],[6,"Staff + shape checks","Checked children place so and mi on a staff and show one shape move on cue."],[2,"Line up on the pulse","March four tas to the door."]]}],"18":[{"b":"Board and marker, Max Found Two Sticks if you have it","i":[[2,"Hello Song, so–mi","Greet on so–mi. One short ta/ti-ti board review."],[5,"Labeling Quarter Note and Eighth Note (book p. 53)","Draw ta/ti-ti/rest in stick notation; students identify. Add note heads and name quarter and eighth notes — still called ta and ti-ti when speaking. Point to mixes while the class speaks. Homeroom: board or document camera."],[6,"Ask the class","“Point to a quarter note. Point to eighth notes.”"],[5,"Read-aloud · Max Found Two Sticks","Use the book guide. Sticks become ta and ti-ti."],[2,"Line up on the pulse","Clap ta ti-ti ta rest to the door."]]},{"b":"Hand drum, optional BX/BM if carried in, Lucy Locket (on this site)","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[5,"The Old Gray Cats Are Sleeping (book pp. 53–54)","Teach from the book (title and page only). Verses alternate sleepy cats (rest feel) and creeping/running mice (jogging pulse). Split class into cats and mice; pantomime safely (jog, do not catch). Match movement to the pulse you support."],[6,"Lucy Locket loud/quiet (book p. 54; also on this site)","Hide a “pocket.” Seeker covers eyes; class sings quieter when far and louder when near — loud is not a shout. Homeroom: hide near the carpet edge so a corner stays visible."],[5,"I Hope! mail game (book pp. 52–54)","Optional if time: title and page only. Conga or hand drum plays a numbered rhythm card after a Valentine delivery. Alternate hands on the drum."],[2,"Line up on the pulse","Quiet mouse steps, then loud lion steps (still kind)."]]},{"b":"Chef’s hat or paper baker hat, board chart for Baker’s Hat, Bounce High Bounce Low, Somebody’s Knocking at Your Door","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[5,"Baker’s Hat (book pp. 54–55)","Teach from the book (title and page only). Speak and clap the baker rhythm; build a so–mi melody with hat visuals so each “Baker’s hat” motive repeats. Pat the pulse; transfer to one barred instrument if available. Pass the hat; holder says what they would bake; class chants the reply four times as a contrasting section."],[5,"Somebody’s Knocking / Bounce High (book p. 55) + 10-second checks","Somebody’s Knocking by title and page only (spiritual; optional woodblock taps). Bounce High, Bounce Low is on this site — bounce on each “bounce,” then to a friend. Homeroom: soft playground ball or beanbag. Rotating check, group B (about 7 children): while the game runs, give each child a 10-second solo: clap one baker rhythm and freeze. Mark Y or N on the record sheet."],[6,"Baker + bounce checks","Checked children clap the baker rhythm and bounce once on the pulse."],[2,"Line up on the pulse","Bounce quietly to the door."]]}],"19":[{"b":"Grade One rhythm cards or board rows (ta, ti-ti, rest), Mole Music if you have it","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[5,"Rhythm Cards (book p. 56)","Show four-beat cards with note heads (title and page only — draw your own rows). Class speaks with ta and ti-ti and touches shoulders on each rest. Point along the beats at first. Homeroom: cards under the document camera or on the board."],[6,"Ask the class","“Where is the rest? Where is ti-ti?”"],[5,"Read-aloud · Mole Music","Use the book guide. Careful playing."],[2,"Line up on the pulse","Speak one card once, then walk."]]},{"b":"Board with a two-line staff, markers","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[5,"Labeling Line and Space Notes (book pp. 56–57)","Two-line staff: a line note sits on a line; a space note sits between lines. Body: fingertips to temples (line note) or one hand on head and one under chin (space note). Children draw line or space notes on the board in short turns."],[6,"Melodic Training review (book p. 57)","Standing circle: echo four-beat so–mi patterns with signs (see p. 50). Optional solfege ladder with only S and M showing."],[5,"Line or space?","You say “line” or “space”; class makes the body shape."],[2,"Line up on the pulse","Line-note arms, then walk."]]},{"b":"Barred instrument set to C pentatonic if possible (remove F and B), optional kangaroo mask, Bounce High","i":[[2,"Hello Song, so–mi","Greet on so–mi."],[5,"The Kangaroo (book pp. 57–58)","Teach from the book (title and page only). Class finds the repeated word “jump.” So–mi echoes in the third phrase. Game: one kangaroo jumps on each “jump,” points to four children for so–mi food answers; class echoes. Then kangaroo and soloists play any two C-pentatonic notes on each “jump” on the barred instrument. Homeroom: one instrument; short turns; soft jumps in place."],[5,"Bounce High review + 10-second checks","On this site — keep the bounce on the pulse. Rotating check, group C (about 7 children): while the game runs, give each child a 10-second solo: speak one four-beat rhythm card, then freeze. Mark Y or N on the record sheet."],[6,"Kangaroo + card checks","Checked children speak one rhythm card and sing one so–mi food answer."],[2,"Line up on the pulse","Quiet kangaroo jumps to the door."]]}],"20":[{"b":"Hand drum, ta/rest cards, heart row","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Ta echo","Echo ta/rest rows."],[8,"Hearts become rows","Put the 4 hearts back up. Replace them with ta and rest cards. Read the row."],[6,"Card change","The teacher swaps one card; the class reads the new row."],[2,"Line up on the pulse","Line up."]]},{"b":"Hand drum, The Jazz Fly (book)","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Pease Porridge","Chant with rests."],[8,"Read-aloud · The Jazz Fly","Use the book guide."],[6,"Read and play","Read rows from the board; play them on the drum."],[2,"Line up on the pulse","Line up."]]},{"b":"Hand drum, woodblock, cards","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Engine, Engine","Chant."],[8,"Row relay","Pairs read a row, then pass the cards on."],[6,"Echo reading + 10-second checks","The drum plays; the class finds the matching row. Rotating check, group D (about 7 children): while the game runs, give each child a 10-second solo: read and clap a four-beat row. Mark Y or N on the record sheet."],[2,"Close + line up","“Read me one row.” Line up."]]}],"21":[{"b":"Hand drum, name cards","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Name echo","Clap names: “Sam” (one), “Ma-ya” (two)."],[8,"One or two?","Pat the pulse and say names. One sound on the beat or two?"],[6,"Name train","Each child claps their name on the pulse; the class echoes."],[2,"Line up on the pulse","Line up saying names."]]},{"b":"Hand drum, Tanka Tanka Skunk! (book)","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Tanka chant","Chant with pats."],[8,"Read-aloud · Tanka Tanka Skunk!","Use the book guide."],[6,"Animal parade","Children choose an animal name; the class claps it."],[2,"Line up on the pulse","Line up."]]},{"b":"Hand drum, woodblock","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Pease Porridge","Chant; find beats with two sounds."],[8,"Name ti-ti","Now name two sounds on a beat: ti-ti."],[6,"Echo game + 10-second checks","Clap names; the class says ta or ti-ti. Rotating check, group A (about 7 children): while the game runs, give each child a 10-second solo: clap their name on the pulse. Mark Y or N on the record sheet."],[2,"Close + line up","“Clap one ti-ti.” Line up."]]}],"22":[{"b":"Hand drum, ta/ti-ti cards","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Ti-ti echo","Echo rows with ta and ti-ti."],[8,"Read ti-ti","Show ti-ti (two joined notes). Read rows: ta ti-ti ta ta."],[6,"Lucy Locket","Sing it; clap the words and say ta or ti-ti."],[2,"Line up on the pulse","Line up."]]},{"b":"Hand drum, Charlie Parker Played Be Bop (book)","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Star Light","Sing it."],[8,"Read-aloud · Charlie Parker Played Be Bop","Use the book guide."],[6,"Lucy Locket game","Hide a “pocket” (small bag); the class sings quietly or loudly as the finder gets closer."],[2,"Line up on the pulse","Line up."]]},{"b":"Hand drum, woodblock, cards","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Rhythm echo","Echo rows."],[8,"Build a row","Pairs build rows with ta and ti-ti, then clap."],[6,"Mystery row + 10-second checks","The drum plays; the class finds the matching row. Rotating check, group B (about 7 children): while the game runs, give each child a 10-second solo: read and clap a row with ta and ti-ti. Mark Y or N on the record sheet."],[2,"Close + line up","“Clap ti-ti ta.” Line up."]]}],"23":[{"b":"Staff, so/mi/la cards","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"So–mi review","Sign See-Saw."],[8,"Meet la","La sits just above so. Sign it (drooping hand). Sing so–la–so."],[6,"Bounce High","Sing Bounce High with signs."],[2,"Line up on the pulse","Line up."]]},{"b":"Up, Up, Down (book)","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Voice climbs","Mi–so–la climb."],[8,"Read-aloud · Up, Up, Down","Use the book guide."],[6,"Bell Horses","Sing with signs."],[2,"Line up on the pulse","Line up."]]},{"b":"Staff, xylophone","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Echo","So–mi–la echoes."],[8,"La on the staff","Place la in the space above so."],[6,"Play it + 10-second checks","G–E–A on the xylophone. Rotating check, group C (about 7 children): while the game runs, give each child a 10-second solo: sing and sign so–la–so–mi. Mark Y or N on the record sheet."],[2,"Close + line up","“Sign la.” Line up."]]}],"24":[{"b":"Hand drum","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Phrase rainbows","Rain, Rain with rainbows."],[8,"Name the phrase","“Each rainbow is a phrase.” Count phrases in Rain, Rain."],[6,"Partner mirror phrases","Partners face each other; A leads a move for phrase 1, B copies; swap for phrase 2."],[2,"Line up on the pulse","Line up."]]},{"b":"Rain, Rain, Go Away! (book)","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Call and response","Sing Somebody’s Knocking: the teacher calls, the class answers."],[8,"Read-aloud · Rain, Rain, Go Away!","Use the book guide."],[6,"Mirror again","New partners, new moves."],[2,"Line up on the pulse","Line up."]]},{"b":"Hand drum","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Somebody’s Knocking","Call and response."],[8,"Child caller","A child sings the call; the class answers."],[6,"Phrase freeze + 10-second checks","Walk during a phrase; freeze at the end of each. Rotating check, group D (about 7 children): while the game runs, give each child a 10-second solo: sing the call in Somebody’s Knocking. Mark Y or N on the record sheet."],[2,"Close + line up","“What is a phrase?” Line up."]]}],"25":[{"b":"Body percussion level cards (snap, clap, pat, stamp)","i":[[2,"Hello on the pulse","Hello Everybody with pats."],[2,"Level warm-up","Snap (or finger taps), clap, pat, stamp softly, 4 each."],[8,"Four levels","Show the cards from top to bottom: snap (head), clap (chest), pat (knees), stamp (feet)."],[6,"Level echo","The teacher plays four beats on one level; the class echoes. Mix levels."],[2,"Line up on the pulse","Line up."]]},{"b":"Level cards, Noisy Nora (book)","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Teddy Bear","Sing with actions."],[8,"Read-aloud · Noisy Nora","Use the book guide."],[6,"Pattern cards","Put two cards up: clap clap pat pat. Play it. Change it."],[2,"Line up on the pulse","Line up."]]},{"b":"Level cards","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Pease Porridge","Chant with pats and claps."],[8,"Build a pattern","Groups build a four-beat body pattern and perform it."],[6,"Level leader + 10-second checks","A child points to levels; the class plays. Rotating check, group A (about 7 children): while the game runs, give each child a 10-second solo: play four beats moving through two body levels. Mark Y or N on the record sheet."],[2,"Close + line up","“Show all four levels.” Line up."]]}],"26":[{"b":"Hand drum, woodblock, A and B cards","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Same/different echo","Same or different patterns."],[8,"Meet A and B","Part A: See-Saw sung. Part B: Engine, Engine chanted. Show A and B cards."],[6,"A/B moves","A = sway. B = march. Switch when the part changes."],[2,"Line up on the pulse","Line up."]]},{"b":"A/B cards, We’re Going on a Bear Hunt (book)","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"A/B moves","Sway and march."],[8,"Read-aloud · We’re Going on a Bear Hunt","Use the book guide."],[6,"Make AB","Groups make an A body pattern and a B instrument pattern."],[2,"Line up on the pulse","Line up."]]},{"b":"A/B cards, drum, woodblock","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"AB review","See-Saw (A), Engine (B)."],[8,"Perform AB","Groups perform their AB."],[6,"Which part? + 10-second checks","The teacher plays; the class holds up A or B. Rotating check, group B (about 7 children): while the game runs, give each child a 10-second solo: say A or B for a short part the teacher plays. Mark Y or N on the record sheet."],[2,"Close + line up","“What does AB mean?” Line up."]]}],"27":[{"b":"Hand drum","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Strong and light","Pat STRONG-light on knees."],[8,"Groups of 2","March: step strong on 1, light on 2. Sing Jim Along Josie."],[6,"Jim Along Josie game","Walk in a circle; the leader changes the move (march, tiptoe, hop) each verse."],[2,"Line up on the pulse","March in 2."]]},{"b":"Hand drum, Trombone Shorty (book)","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Sway in 4","Sway: STRONG-light-light-light."],[8,"Read-aloud · Trombone Shorty","Use the book guide."],[6,"Punchinella","Learn by echo; the child in the middle does a move, the class copies."],[2,"Line up on the pulse","Line up."]]},{"b":"Hand drum, triangle","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Punchinella","Sing it."],[8,"March or sway?","The teacher plays 2 or 4; the class marches or sways. Triangle on beat 1."],[6,"Beat-1 leader + 10-second checks","A child plays beat 1 on the triangle. Rotating check, group C (about 7 children): while the game runs, give each child a 10-second solo: march in 2 with a strong beat 1. Mark Y or N on the record sheet."],[2,"Close + line up","“March in 2.” Line up."]]}],"28":[{"b":"Hand drum","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Speech echo","“Rain-y day” (ti-ti ta), echo."],[8,"Speech ostinato","Say “rain-y day” over and over while the teacher sings Rain, Rain."],[6,"Two jobs","Half says the ostinato, half sings. Swap."],[2,"Line up on the pulse","Line up saying the ostinato."]]},{"b":"Hand drum, sticks, Max Found Two Sticks (book)","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Acka Backa","Chant it."],[8,"Read-aloud · Max Found Two Sticks","Use the book guide."],[6,"Stick ostinato","Play “rain-y day” on sticks under Rain, Rain."],[2,"Line up on the pulse","Line up."]]},{"b":"Sticks, drum, woodblock","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"New ostinato","Groups invent a two-word ostinato (“hot soup”)."],[8,"Layer it","Groups perform their ostinato under Acka Backa."],[6,"Ostinato leader + 10-second checks","A child starts an ostinato; the class joins. Rotating check, group D (about 7 children): while the game runs, give each child a 10-second solo: say or play a speech ostinato four times. Mark Y or N on the record sheet."],[2,"Close + line up","“What is an ostinato?” Line up."]]}],"29":[{"b":"Woodblock, triangle, 1 xylophone","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Wood and metal voices","Say “wood” and “metal” in the voice of each sound."],[8,"Pitched wood/metal","Play the xylophone (wood bars) and the Studio glockenspiel (metal). Match: xylophone = woodblock family; glockenspiel = triangle family."],[6,"Eyes-closed sort","Wood or metal? Point to the mat."],[2,"Line up on the pulse","Line up."]]},{"b":"Woodblock, triangle, Zin! Zin! Zin! A Violin (book)","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"See-Saw","Sing and play on the xylophone."],[8,"Read-aloud · Zin! Zin! Zin! A Violin","Use the book guide."],[6,"Wood and metal stations","Xylophone station and triangle/bells station (Studio on the screen)."],[2,"Line up on the pulse","Line up."]]},{"b":"Woodblock, triangle, xylophone","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Bounce High","Sing."],[8,"Play pitches","Bounce High on the xylophone (G–E–A)."],[6,"Guess the family + 10-second checks","The teacher plays; the class says wood or metal, pitched or not. Rotating check, group A (about 7 children): while the game runs, give each child a 10-second solo: say wood or metal for one sound. Mark Y or N on the record sheet."],[2,"Close + line up","“Name a pitched wood instrument.” Line up."]]}],"30":[{"b":"Repeat sign card, hand drum","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Echo","Echo a row twice."],[8,"The repeat sign","Show two dots and double lines. “Go back and do it again.” Clap a row with the sign; clap it twice."],[6,"Repeat game","Play a row with or without the sign; the class claps once or twice."],[2,"Line up on the pulse","Line up."]]},{"b":"Repeat card, Pete the Cat: I Love My White Shoes (book)","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Rain, Rain twice","With the repeat sign."],[8,"Read-aloud · Pete the Cat","Use the book guide."],[6,"Find the repeat","Show row cards; a child adds the repeat sign."],[2,"Line up on the pulse","Line up."]]},{"b":"Repeat card, woodblock","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"See-Saw twice","Repeat sign."],[8,"Play with repeats","Groups play a row with a repeat on woodblock."],[6,"Listening + 10-second checks","A short listening piece chosen for this week. Where does it repeat? Rotating check, group B (about 7 children): while the game runs, give each child a 10-second solo: clap a row with a repeat sign (twice). Mark Y or N on the record sheet."],[2,"Close + line up","“What do the dots mean?” Line up."]]}],"31":[{"b":"A/B cards, drum, ta/rest cards","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"AB review","Sway A, march B."],[8,"ABA","A: See-Saw. B: a ta/rest row. A: See-Saw again. Show cards A B A."],[6,"ABA moves","Move to show A, B, A."],[2,"Line up on the pulse","Line up."]]},{"b":"A/B cards, From Head to Toe (book)","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Pease Porridge","Chant."],[8,"Read-aloud · From Head to Toe","Use the book guide."],[6,"Compose B","Pairs make a B with 4 ta/rest cards."],[2,"Line up on the pulse","Line up."]]},{"b":"Cards, drum, woodblock","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"See-Saw","Sing A."],[8,"Perform ABA","Pairs play their B between two A’s."],[6,"Name the form + 10-second checks","The class names the form. Rotating check, group C (about 7 children): while the game runs, give each child a 10-second solo: play their B row on the drum between two A’s. Mark Y or N on the record sheet."],[2,"Close + line up","“What does ABA mean?” Line up."]]}],"32":[{"b":"Hand drum, shaker","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Swing arms","Swing arms left-right on two big beats."],[8,"Hickory swing","Say Hickory Dickory Dock and swing arms. Feel two big beats, each with three little ticks."],[6,"Swing walk","Walk the big beats; shakers tick the little ones."],[2,"Line up on the pulse","Line up."]]},{"b":"Shaker, Giraffes Can’t Dance (book)","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Jack and Jill","Learn by echo."],[8,"Read-aloud · Giraffes Can’t Dance","Use the book guide."],[6,"Swing or march?","The teacher plays; the class swings or marches."],[2,"Line up on the pulse","Line up."]]},{"b":"Drum, shakers","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Jack and Jill","Sing with swings."],[8,"Swing band","Drum on big beats, shakers on little ones."],[6,"Swing leader + 10-second checks","A child chooses swing or march. Rotating check, group D (about 7 children): while the game runs, give each child a 10-second solo: swing arms on the big beats of Hickory Dickory Dock. Mark Y or N on the record sheet."],[2,"Close + line up","“Show me swing.” Line up."]]}],"33":[{"b":"Ta, ti-ti, rest cards","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Rhythm echo","Echo rows."],[8,"Make a piece","Each child builds a four-beat piece with cards."],[6,"Share","Volunteers play their piece; the class echoes."],[2,"Line up on the pulse","Line up."]]},{"b":"Cards, Mole Music (book)","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Bounce High","Sing."],[8,"Read-aloud · Mole Music","Use the book guide."],[6,"Practise","Children practise their piece on the drum or woodblock."],[2,"Line up on the pulse","Line up."]]},{"b":"Cards, drum, woodblock","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Rain, Rain","Sing."],[8,"Play your piece","More volunteers share."],[6,"Class choice + 10-second checks","Choose two pieces for the concertette. Rotating check, group A (about 7 children): while the game runs, give each child a 10-second solo: play their own four-beat piece. Mark Y or N on the record sheet."],[2,"Close + line up","“Show your piece to a partner.” Line up."]]}],"34":[{"b":"Program list, drum","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Warm voices","Slides and so–mi–la echoes."],[8,"Plan the concertette","Choose 3 items: a song, a pulse or ostinato piece, and two student pieces. Practise."],[6,"Audience manners","Half performs, half is the audience; swap."],[2,"Line up on the pulse","Line up."]]},{"b":"Program, Never Play Music Right Next to the Zoo (book)","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"O Canada","Sing the first phrase; stand tall."],[8,"Read-aloud · Never Play Music Right Next to the Zoo","Use the book guide."],[6,"Rehearse","Run the program once."],[2,"Line up on the pulse","Line up."]]},{"b":"Program","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Warm up","Voices."],[8,"The concertette","Perform the 4-minute program for a small audience (buddy class or principal)."],[6,"Celebrate + 10-second checks","Tell one thing we did well. Rotating check, group B (about 7 children): while the game runs, give each child a 10-second solo: perform their part in the concertette. Mark Y or N on the record sheet."],[2,"Close + line up","Line up."]]}],"35":[{"b":"Station cards, drum, xylophone, ta/rest cards","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Warm up","Voices and body levels."],[8,"Station preview","Walk through the 5 stations: pulse, rest, so–mi, mallet bounce, AB."],[6,"Practice stations","Groups rotate through practice."],[2,"Line up on the pulse","Line up."]]},{"b":"Station cards","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"See-Saw","Sing with signs."],[8,"Picture check","Children show each station; mark Y/N on the record sheet."],[6,"Free play","Waiting groups use the Studio."],[2,"Line up on the pulse","Line up."]]},{"b":"Station cards, Because (book)","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Pease Porridge","Chant."],[8,"Read-aloud · Because","Use the book guide."],[6,"Finish checks + 10-second checks","Finish the children not yet checked. Rotating check, group C (about 7 children): while the game runs, give each child a 10-second solo: show one station (pulse, rest, so–mi, mallet or AB). Mark Y or N on the record sheet."],[2,"Close + line up","“What are you proud of?” Line up."]]}],"36":[{"b":"Song list, drum","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Voice warm-up","Four voices."],[8,"Requests","Children vote for favourite songs and games from the year."],[6,"Game time","Play a favourite game (Bee Bee, Bow Wow Wow, Punchinella)."],[2,"Line up on the pulse","Line up."]]},{"b":"We Belong to the Drum (book)","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Listening chair","Sit calmly."],[8,"Read-aloud · We Belong to the Drum","Use the book guide."],[6,"Listening","Listen to a recording chosen with your school’s guidance. What do you notice?"],[2,"Line up on the pulse","Line up."]]},{"b":"Song list","i":[[2,"Hello on the pulse","Hello Everybody."],[2,"Requests","Sing favourites."],[8,"Student choice","Children lead games."],[6,"Goodbye song + 10-second checks","Sing goodbye. Rotating check, group D (about 7 children): while the game runs, give each child a 10-second solo: lead a favourite song or game. Mark Y or N on the record sheet."],[2,"Close + line up","“What was your favourite?” Line up."]]}]};
